{
  DCMI_HandleTypeDef* hdcmi = ( DCMI_HandleTypeDef* )((DMA_HandleTypeDef* )hdma)->Parent;

  if(hdcmi->DMA_Handle->ErrorCode != HAL_DMA_ERROR_FE)
