  else
  {
    /* Update the error code */
    hi2c->ErrorCode |= HAL_I2C_ERROR_INVALID_CALLBACK;

/* Return error status */
    status =  HAL_ERROR;
  }

/* Release Lock */
  __HAL_UNLOCK(hi2c);
  return status;
}

