    else
    {
      /* Process unlocked */
      __HAL_UNLOCK(hqspi);
    }
  }
  else
  {
    status = HAL_BUSY;

/* Process unlocked */
    __HAL_UNLOCK(hqspi);
  }

/* Return function status */
  return status;
}

