  * @retval HAL status
  */
HAL_StatusTypeDef HAL_QSPI_SetFlashID(QSPI_HandleTypeDef *hqspi, uint32_t FlashID)
{
  HAL_StatusTypeDef status = HAL_OK;

/* Check the parameter */
  assert_param(IS_QSPI_FLASH_ID(FlashID));

/* Process locked */
  __HAL_LOCK(hqspi);

if(hqspi->State == HAL_QSPI_STATE_READY)
