    /* Synchronize init structure with new FlashID value */
    hqspi->Init.FlashID = FlashID;

/* Configure QSPI FlashID */
    MODIFY_REG(hqspi->Instance->CR, QUADSPI_CR_FSEL, FlashID);
  }
  else
  {
    status = HAL_BUSY;
  }

/* Process unlocked */
  __HAL_UNLOCK(hqspi);

/* Return function status */
  return status;
}

